using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using FlyEditor.Flight;
namespace FlyEditor.Editor {
 // Reference study, not a claim that the compressed diagram has been fully decoded.
 // Every checkpoint is generated by the same runtime folds as the workbench.
 public static class JetStudyAudit {
    public static void Render(PaperSheet paper,string folder,string name,PaperCornerPull pull=null)
    {
        var scene=EditorSceneManager.NewPreviewScene();var go=new GameObject("Audit paper");var cameraGo=new GameObject("Audit camera");
        UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(go,scene);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(cameraGo,scene);
        var mesh=new Mesh();var type=typeof(PaperSheet).Assembly.GetType("FlyEditor.Flight.FoldMesh");
        var method=type.GetMethod("Build");var info=method.GetParameters();var args=new object[info.Length];
        for(int i=0;i<args.Length;i++)args[i]=info[i].HasDefaultValue?info[i].DefaultValue:null;
        args[0]=mesh;args[1]=paper;args[2]=null;args[3]=0f;
        var points=new List<PaperSheet.FoldVertex>();args[4]=points;args[10]=pull;
        args[18]=Vector3.zero;
        method.Invoke(Activator.CreateInstance(type,true),args);mesh.RecalculateBounds();
        go.AddComponent<MeshFilter>().sharedMesh=mesh;
        var material=new Material(Shader.Find("FlyEditor/PaperFlight"));go.AddComponent<MeshRenderer>().sharedMaterial=material;
        var cam=cameraGo.AddComponent<Camera>();cam.cameraType=CameraType.Preview;cam.orthographic=true;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.91f,.94f,.92f);
        var center=mesh.bounds.center;cam.transform.position=center+new Vector3(2,16,-12);cam.transform.LookAt(center);cam.orthographicSize=Mathf.Max(4f,mesh.bounds.size.magnitude*.58f);
        cam.nearClipPlane=.1f;cam.farClipPlane=100;cam.scene=scene;
        var rt=new RenderTexture(1000,760,24);var tex=new Texture2D(1000,760,TextureFormat.RGB24,false);var old=RenderTexture.active;
        try {cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1000,760),0,0);tex.Apply();File.WriteAllBytes(Path.Combine(folder,name+".png"),tex.EncodeToPNG());}
        finally {cam.targetTexture=null;RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(material);EditorSceneManager.ClosePreviewScene(scene);}
    }

  static PaperSheet sheet;static string folder;
  static void Check(bool ok,string m){if(!ok)throw new Exception("[JetStudy] "+m);}
  static void Save(string n){ReverseDirectionVerification.Geometry(sheet.Faces);PetalFoldingVerification.Replay(sheet);Render(sheet,folder,n);File.WriteAllText(Path.Combine(folder,n+".json"),JsonUtility.ToJson(new ResearchSave{paperFolds=sheet.Recipe()},true));}
  static bool Turn(Vector2 normal,float offset,int side,float angle,int anchor=0,bool all=true){
   var step=new FoldStep{creaseNormal=normal,creaseOffset=offset,side=side,anchor=anchor,flap=all?0:anchor+1,connectedPanel=true,continuousHinge=true,neutralContacts=true,compactLayers=true};
   var turn=sheet.Plan(step);if(turn==null||Mathf.Abs(turn.Constrain(angle)-angle)>.001f)return false;
   Sweep(turn,angle);Check(sheet.Finish(turn,angle),"commit");return true;
  }
  static Vector2 Handle(PaperSheet.Face basis,Vector2 point){foreach(var f in sheet.Faces)if(f.Contains(point)){var m=f.material.MultiplyPoint3x4(new Vector3(point.x,0,point.y));var p=basis.material.inverse.MultiplyPoint3x4(m);return new Vector2(p.x,p.z);}throw new Exception("Missing diagram handle "+point);}
  static bool Align(Vector2 tip,Vector2 edge,Vector2 targetA,Vector2 targetB){
   for(int i=0;i<sheet.Faces.Count;i++){var f=sheet.Faces[i];if(!f.Contains(tip)||!f.Contains(edge))continue;
    var step=new FoldStep{anchor=i,flap=0,cornerPull=true,customFlanks=true,flexible=true,closeFlat=true,adaptiveCreases=true,continuousHinge=true,neutralContacts=true,compactLayers=true,pullTip=tip,pullStop=edge,pullLeft=Handle(f,targetA),pullRight=Handle(f,targetB)};
    var p=PaperCornerPull.Create(sheet,step);if(p==null||!p.UsesEdgeMatch)continue;
    foreach(int sign in new[]{1,-1}){if(!p.TryMove(0,sign*180,out var reached)||Mathf.Abs(reached-sign*180)>.001f)continue;
     for(int a=0;a<=180;a+=3){Check(p.Pose(sign*a),"align sweep");ReverseDirectionVerification.Geometry(p.Preview);}Check(sheet.FinishPull(p,sign*180),"align commit");return true;}
   }return false;
  }
  static void Sweep(PaperSheet.Turn turn,float angle){
   var method=typeof(PaperSheet).GetMethod("TryPreviewTurn",BindingFlags.Instance|BindingFlags.NonPublic);var faces=new System.Collections.Generic.List<PaperSheet.Face>();
   for(int a=0;a<=Mathf.Abs(angle);a+=3){Check((bool)method.Invoke(sheet,new object[]{turn,Mathf.Sign(angle)*a,faces}),"rigid sweep");ReverseDirectionVerification.Geometry(faces);}
  }
  static bool Wing(bool left){
   var root=new Vector2(5.5f,11.453157f);var edge=new Vector2(left?4.2095f:6.7905f,11.9877f);var d=edge-root;var n=new Vector2(-d.y,d.x).normalized;
   var point=new Vector2(left?5:6,12.4f);int anchor=-1,top=int.MinValue;
   for(int i=0;i<sheet.Faces.Count;i++){var f=sheet.Faces[i];if(f.Contains(point)&&f.layer>top){anchor=i;top=f.layer;}}
   if(anchor<0)return false;int side=Vector2.Dot(n,point-root)>0?1:-1;
   var step=new FoldStep{creaseNormal=n,creaseOffset=Vector2.Dot(n,root),side=side,anchor=anchor,flap=anchor+1,connectedPanel=true,continuousHinge=true,neutralContacts=true,compactLayers=true};
   var turn=sheet.Plan(step);Debug.Log("[JetStudy] lower wing "+left+" anchor="+anchor+" plan="+(turn!=null)+" allowed="+(turn==null?"none":turn.Constrain(180)+" / "+turn.Constrain(-180)));
   if(turn==null)return false;foreach(float a in new[]{180f,-180f})if(Mathf.Abs(turn.Constrain(a)-a)<.001f){Sweep(turn,a);return sheet.Finish(turn,a);}return false;
  }
  static bool Spread(bool upper){
   int anchor=-1,layer=upper?int.MinValue:int.MaxValue;var point=new Vector2(4.8f,10.5f);
   for(int i=0;i<sheet.Faces.Count;i++){var f=sheet.Faces[i];if(f.Contains(point)&&(upper?f.layer>layer:f.layer<layer)){anchor=i;layer=f.layer;}}
   if(anchor<0){Debug.Log("[JetStudy] spread: no wing under contact");return false;}
   var line=new FoldStep{creaseNormal=Vector2.right,creaseOffset=5.25f,side=-1,anchor=anchor,flap=anchor+1,connectedPanel=true,continuousHinge=true,neutralContacts=true,compactLayers=true};
   var p=sheet.Plan(line);Debug.Log("[JetStudy] spread "+upper+" anchor="+anchor+" layer="+layer+" plan="+(p!=null)+" allowed="+(p==null?"none":p.Constrain(180)+" / "+p.Constrain(-180))+" parts="+(p==null?"none":p.movingFaces.Count+" / "+p.fixedFaces.Count));
   return p!=null&&sheet.Finish(p,upper?90:-90);
  }
  [MenuItem("Tools/FlyEditor/Validation/Rebuild jet study - INCOMPLETE")]
  public static void Run(){folder=Environment.GetEnvironmentVariable("FLYEDITOR_JET");if(string.IsNullOrEmpty(folder))folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../../Docs/OrigamiAudit/jet-study/generated"));Directory.CreateDirectory(folder);sheet=new PaperSheet();
   var step=new FoldStep{cornerPull=true,customFlanks=true,closeFlat=true,flexible=true,adaptiveCreases=true,coordinatedCreases=true,regionalPull=true,anchor=0,flap=1,pullTip=new Vector2(11,5.5f),pullStop=Vector2.one*5.5f,pullLeft=new Vector2(11,0),pullRight=new Vector2(11,11)};
   var gather=PaperCornerPull.Create(sheet,step);Check(gather!=null&&gather.UsesRadialGather,"triangle base plan");for(int a=0;a<=180;a+=3){Check(gather.Pose(a),"base sweep "+a);ReverseDirectionVerification.Geometry(gather.Preview);}Check(sheet.FinishPull(gather,180),"base close");Save("01-triangle-base");
   Check(Align(new Vector2(5.5f,5.5f),new Vector2(0,11),new Vector2(5.5f,8.25f),new Vector2(5.5f,11)),"left edge to centre");Save("02-left-edge");
   Check(Align(new Vector2(5.5f,5.5f),new Vector2(11,11),new Vector2(5.5f,8.25f),new Vector2(5.5f,11)),"right edge to centre");Save("03-kite-base");
   float shoulder=5.5f*Mathf.Tan(22.5f*Mathf.Deg2Rad);
   Check(Align(new Vector2(5.5f,5.5f),new Vector2(5.5f-shoulder,11),new Vector2(5.5f,8.25f),new Vector2(5.5f,11)),"left second edge");Save("04-narrow-left");
   Check(Align(new Vector2(5.5f,5.5f),new Vector2(5.5f+shoulder,11),new Vector2(5.5f,8.25f),new Vector2(5.5f,11)),"right second edge");Save("05-narrow-nose");
   var lines=new System.Collections.Generic.List<string>();for(int i=0;i<sheet.Faces.Count;i++){var f=sheet.Faces[i];lines.Add(i+" layer="+f.layer+" "+string.Join(";",Array.ConvertAll(f.points,p=>p.ToString("F4"))));}File.WriteAllLines(Path.Combine(folder,"faces.txt"),lines);
   if(Wing(true)){Save("06-left-wing-study");if(Wing(false))Save("07-right-wing-study");}
   if(Turn(Vector2.right,5.5f,1,180)){Save("08-fuselage-study");if(Spread(true)){Save("09-upper-wing-study");if(Spread(false))Save("10-wing-opening-study");}}
   Save("partial");
   Debug.Log("[JetStudy] verified nose, side tabs and fuselage, "+sheet.Count+" runtime actions; target aircraft NOT complete.");
  }
 }
}


